/*-- Generales --*/

:root {
	/* Colores */
	/*--RMAIN: 188;
	--GMAIN: 158;
	--BMAIN: 224;*/
	--RMAIN: 124;
	--GMAIN: 28;
	--BMAIN: 135;

	--clareado-forzado: 1.5;

	--color-resaltado1: rgb(calc(var(--RMAIN)*var(--clareado-forzado)), calc(var(--GMAIN)*var(--clareado-forzado)), calc(var(--BMAIN)*var(--clareado-forzado)));
	--color-resaltado2: rgb(calc(var(--RMAIN)/2.35), calc(var(--GMAIN)/2.63), calc(var(--BMAIN)/1.75)); /*503c80*/
	--color-fondo1: rgb(calc(var(--RMAIN)/7.52), 0, calc(var(--BMAIN)/4.48)); /*rgb(25, 0, 50);*/
	--color-fondo2: rgb(calc(var(--RMAIN)/2.69), calc(var(--GMAIN)/2.78), calc(var(--BMAIN)/2.13)); /*rgb(70, 55, 105);*/
	--color-fondo3: rgb(calc(var(--RMAIN)/20.89), calc(var(--GMAIN)/30.6), calc(var(--BMAIN)/11.79)); /*rgb(9, 5, 19);*/
	--color-texto-base: rgb(calc((var(--RMAIN)*0.78) + 200), calc((var(--GMAIN)*0.78) + 200), calc((var(--BMAIN)*0.78) + 200)); /*#e8e8e8;*/
	--color-titulo: #ffffff;

	/* Textos */
	--interespaciado-textual: 150%;
	--redondeado-imagen: 2%;

	/* Fuentes */

	--fuente-base: "Fira Sans";
	--fuente-negrita: "Fira Sans Bold";
	--fuente-cabeceras: var(--fuente-negrita);
}

/*-- Fuentes --*/

@font-face {
	font-family: "Fira Sans";
	src: url("data:@file/x-font-ttf;base64,");
}

@font-face {
	font-family: "Fira Sans Bold";
	src: url("data:@file/x-font-ttf;base64,");
}

/*-- Animaciones --*/

@keyframes fadeIn {
	0% {
		opacity: 0;
		transform: translateX(100%);
	}
	100% {
		opacity: 1;
		transform: translateX(0); /* Sale hacia la derecha */
	}
}

@keyframes imgShadow {
	0% {
		box-shadow: 5px 5px 5px 5px rgba(0, 0, 0, 0);
	}
	100% {
		box-shadow: 5px 5px 5px 5px rgba(0, 0, 0, 0.4);
	}
}

