html, body {
	margin: 0;
	color: var(--color-texto-base);
	font-family: var(--fuente-base);
	height: 100%; /* Asegura que los padres tengan altura completa */
	/* Desactivar los colores */
	/*animation: RMAIN 6s infinite alternate, GMAIN 8s infinite alternate, BMAIN 10s infinite alternate;*/animation: GMAIN 8s infinite alternate;
}

.content {
	margin-left: 20%;
	width: 80%;
	padding-top: 20px;
	min-height: 100vh; /* Altura mínima del viewport */
	box-sizing: border-box; /* Incluye padding en el cálculo del ancho/alto */

	background:
		linear-gradient(0deg, var(--color-fondo1), transparent),
		linear-gradient(270deg, var(--color-fondo1), var(--color-fondo2));
		

	overflow: hidden;
	display: flex;
	flex-direction: column;
}

/* Selecciona todos los hijos directos de content MENOS el footer */
.content > *:not(footer, img) {
	padding-left: 2%; /* El valor que tenías antes en .content */
	padding-right: 2%; /* El valor que tenías antes en .content */
}

h1, h2, h3, h4, h5, h6 {
	color: var(--color-titulo);
	font-family: var(--fuente-cabeceras);
	letter-spacing: 1.5px;
}

h1 {
	text-align: center;
}

a {
	text-decoration: none;
	color: var(--color-resaltado1);
	transition: color 500ms;
}

button {
	color: var(--color-resaltado1);
	transition: color 500ms, background-color 500ms;
	font-size: 100%;
	text-align: left;
}

a:hover, button:hover {
	text-decoration: underline;
	color: var(--color-titulo);
	background-color: var(--color-resaltado2) !important;
}

img {
	margin: 2ch;
	display: block;
	margin-left: auto;
	margin-right: auto;
	border-radius: var(--redondeado-imagen);
	max-width: 100%;
	max-height: 500px;

	transition: box-shadow 0.5s ease;
}

img:hover {
	box-shadow: 0px 0px 10px 10px rgba(0, 0, 0, 0.5);
	transform: scale(1.005);
}

footer {
	padding: 5px 5% 15px 5%;
	margin-top: auto;
	background: linear-gradient(0deg, var(--color-fondo2), transparent);
	width: 90%;
	display: flex;
	align-items: center;
	justify-content: space-between;
}

footer p {
	margin: 0;
}

.rrss {
	display: flex;
	gap: 20px;
}

.rrss img {
	height: 30px;
	margin: 0;
}

td {
	text-align: center;
}

.quote {
	border: 5px solid var(--color-resaltado2);
	border-radius: 4px;
	padding: 5px 10px 10px 5px;
	margin: 10px 20px;
	opacity: 0;
}

.quote.terminal {
	animation-name: fadeIn;
	animation-duration: 2s;
	animation-fill-mode: forwards; /* Se queda visible al terminar */
	/* animation-timing-function: ease-out; (Opcional: para suavizar) */
	opacity: 0;
}

.quote h1, .quote h2, .quote h3, .quote h4, .quote h5, .quote h6 {
	text-decoration: underline;
}

.cuatroXcuatroIMG {
	display: grid;
	grid-template-columns: repeat(2, 1fr);
	gap: 12px;
	max-width: 1200px;
	margin: 0 auto;
}

.cuatroXcuatroIMG img {
	width: 100%;
	height: 200px;           /* altura fija; cambia según quieras */
	object-fit: cover;       /* rellena la celda recortando proporcionalmente */
	display: block;
	border-radius: 6px;
}

/* SIDEBAR */

.sidebar {
	position: fixed; /* Mantiene el sidebar visible siempre */
	top: 0;
	left: 0;
	width: 20%;
	height: 100%;
	color: white;
	padding: 20px;
	box-sizing: border-box;
	overflow-y: auto;

	background:
		linear-gradient(180deg, transparent, var(--color-fondo1)),
		linear-gradient(270deg, var(--color-fondo2), var(--color-fondo1));

}

.sidebar h2 {
	margin-top: 0;
	margin-left: auto;
	margin-right: auto;
	max-width: fit-content;
}
  
.sidebar ul {
	list-style-type: none;
	padding: 0;
}
  
.sidebar ul li {
	margin: 15px 0;
	border: 4px solid var(--color-fondo2);
	border-radius: 10px;
}

.sidebar ul li button {
	padding: 10px;
	border: none;
	background-color: transparent;
	border-radius: 6px;
	width: 100%;
	height: 100%;
}

#seleccionado {
	background-color: var(--color-resaltado2);
}